  List<String>orientationGroups=new ArrayList<>();for(int h:new int[]{31,40,64}){Object v=glyph(40,40,2,h,"VERTICAL"),horizontal=glyph(40,40,2,h,"HORIZONTAL");if(v.equals(horizontal))throw new IllegalStateException("orientation equality contract");Object va=gc.getConstructor(int.class,int.class,rt).newInstance(40,40,call(v,"getRunTable")),ha=gc.getConstructor(int.class,int.class,rt).newInstance(40,40,call(horizontal,"getRunTable"));List<Object>items=new ArrayList<>();for(Object g:List.of(v,va,horizontal,ha))items.add(gi.getConstructor(gc,int.class).newInstance(g,0));orientationGroups.add("{\"cases\":["+record(builders.get(0),"same-pixels-distinct-orientation",items)+"]}");}
